    this.dir = 'down'; Sound.sfx('exclaim'); this.excl = 30; yield* wait(30);
    yield* say('咦……？腳下……在發光？');
    Sound.sfx('charge'); Game.shake = 30; yield* tween(50, t => this.circle = 0.35 + t * 0.65);
    yield* say('等、等一下——！', { auto: 30 });
