      const g = x.createRadialGradient(cx, cy, 2, cx, cy, R); g.addColorStop(0, 'rgba(200,250,255,0.9)'); g.addColorStop(1, 'rgba(80,200,255,0)'); x.fillStyle = g; x.beginPath(); x.ellipse(cx, cy, R, R * 0.34, 0, 0, 7); x.fill();
